/* arm_qp_qpsol:(h[45x45,255nz],g[45],a[355x45,2140nz],lba[355],uba[355],lbx[45],ubx[45],x0[45],lam_x0[45],lam_a0[355],q[0x45],p[])->(x[45],cost,lam_a[355],lam_x[45]) */
static int casadi_f2(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  OSQPSolver *work=casadi_f2_mem[mem];
  casadi_int i, n, offset;
  /* Set objective */
  if (arg[1]) {
    casadi_copy(arg[1], 45, w);
  } else {
    casadi_clear(w, 45);
  }
  if (osqp_update_data_vec(work, w, 0, 0)) return 1;
  /* Set bounds */
  if (arg[5]) {
    casadi_copy(arg[5], 45, w);
  } else {
    casadi_fill(w, 45, -casadi_inf);
  }
  if (arg[3]) {
    casadi_copy(arg[3], 355, w+45);
  } else {
    casadi_fill(w+45, 355, -casadi_inf);
  }
  if (arg[6]) {
    casadi_copy(arg[6], 45, w+400);
  } else {
    casadi_fill(w+400, 45, casadi_inf);
  }
  if (arg[4]) {
    casadi_copy(arg[4], 355, w+445);
  } else {
    casadi_fill(w+445, 355, casadi_inf);
  }
  /* Convert C++ infinity values to OSQP infinity */
  casadi_clip_min(w, 800, -OSQP_INFTY, 0);
  casadi_clip_max(w, 800, OSQP_INFTY, 0);
  if (osqp_update_data_vec(work, 0, w, w+400)) return 1;
  /* Project Hessian */
  casadi_tri_project(arg[0], casadi_s0, w, 0);/* Get constraint matrix */
  offset = 0;
  for (i=0; i< 45; ++i) {
    w[150+offset] = 1;
    offset++;
    n = casadi_s1[i+1]-casadi_s1[i];
    casadi_copy(arg[2]+casadi_s1[i], n, w+offset+150);
    offset+= n;
  }
  /* Pass Hessian and constraint matrices */
  if (osqp_update_data_mat(work, w, 0, 150, w+150, 0, 2185)) return 1;
  osqp_cold_start(work);
  osqp_update_rho(work, 1.0000000000000001e-01);
  if (osqp_warm_start(work, arg[7], OSQP_NULL)) return 1;
  if (arg[8]) {
    casadi_copy(arg[8], 45, w);
  } else {
    casadi_clear(w, 45);
  }
  if (arg[9]) {
    casadi_copy(arg[9], 355, w+45);
  } else {
    casadi_clear(w+45, 355);
  }
  if (osqp_warm_start(work, OSQP_NULL, w)) return 1;
  if (osqp_solve(work)) return 1;
  if (res[1]) casadi_copy(&work->info->obj_val, 1, res[1]);
  if (res[0]) casadi_copy(work->solution->x, 45, res[0]);
  if (res[3]) casadi_copy(work->solution->y, 45, res[3]);
  if (res[2]) casadi_copy(work->solution->y+45, 355, res[2]);
  if (work->info->status_val != OSQP_SOLVED) {
    if (work->info->status_val == OSQP_PRIMAL_INFEASIBLE || work->info->status_val == OSQP_MAX_ITER_REACHED || work->info->status_val == OSQP_DUAL_INFEASIBLE || work->info->status_val == OSQP_PRIMAL_INFEASIBLE_INACCURATE || work->info->status_val == OSQP_DUAL_INFEASIBLE_INACCURATE || work->info->status_val == OSQP_NON_CVX) {
      return 4;
    } else {
      return 1;
    }
  }
  return 0;
  return 0;
}

int casadi_f2_alloc_mem(void) {
  return casadi_f2_mem_counter++;
}

int casadi_f2_init_mem(int mem) {
  OSQPCscMatrix A, H;
  OSQPInt A_colind[46], A_row[2185], H_colind[46], H_row[150], i;
  OSQPSettings settings;
  casadi_real dummy[2185];
  casadi_clear(dummy, 2185);
  for (i=0;i<2185;++i) A_row[i] = casadi_s2[i];
  for (i=0;i<46;++i) A_colind[i] = casadi_s3[i];
  for (i=0;i<150;++i) H_row[i] = casadi_s4[i];
  for (i=0;i<46;++i) H_colind[i] = casadi_s5[i];
  A.m = 400;
  A.n = 45;
  A.nz = 2185;
  A.nzmax = 2185;
  A.x = dummy;
  A.i = A_row;
  A.p = A_colind;
  H.m = 45;
  H.n = 45;
  H.nz = 150;
  H.nzmax = 150;
  H.x = dummy;
  H.i = H_row;
  H.p = H_colind;
  struct
  {
      OSQPInt n;
      OSQPInt m;
      OSQPCscMatrix * P;
      OSQPCscMatrix * A;
      OSQPFloat * q;
      OSQPFloat * l;
      OSQPFloat * u;
  } data;
  data.n = 45;
  data.m = 400;
  data.P = &H;
  data.q = dummy;
  data.A = &A;
  data.l = dummy;
  data.u = dummy;
  osqp_set_default_settings(&settings);
  settings.rho = 1.0000000000000001e-01;
  settings.sigma = 9.9999999999999995e-07;
  settings.scaling = 10;
  settings.adaptive_rho = 1;
  settings.adaptive_rho_interval = 50;
  settings.adaptive_rho_tolerance = 5.;
  settings.max_iter = 4000;
  settings.eps_abs = 1.0000000000000000e-03;
  settings.eps_rel = 1.0000000000000000e-03;
  settings.eps_prim_inf = 1.0000000000000000e-04;
  settings.eps_dual_inf = 1.0000000000000000e-04;
  settings.alpha = 1.6000000000000001e+00;
  settings.delta = 9.9999999999999995e-07;
  settings.polishing = 0;
  settings.polish_refine_iter = 3;
  settings.verbose = 1;
  settings.scaled_termination = 0;
  settings.check_termination = 25;
  settings.warm_starting = 0;
  return osqp_setup(&casadi_f2_mem[mem], data.P, data.q, data.A, data.l, data.u, data.m, data.n, &settings)!=0;
}

void casadi_f2_free_mem(int mem) {
  osqp_cleanup(casadi_f2_mem[mem]);
}

int casadi_f2_checkout(void) {
  int mid;
  if (casadi_f2_unused_stack_counter>=0) {
    return casadi_f2_unused_stack[casadi_f2_unused_stack_counter--];
  } else {
    if (casadi_f2_mem_counter==CASADI_MAX_NUM_THREADS) {
      return -1;
    }
    mid = casadi_f2_alloc_mem();
    if (mid<0) {
      return -1;
    }
    if (casadi_f2_init_mem(mid)) {
      return -1;
    }
    return mid;
  }
}

void casadi_f2_release(int mem) {
  casadi_f2_unused_stack[++casadi_f2_unused_stack_counter] = mem;
  return;
}

void casadi_f2_incref(void) {
  casadi_f2_ref_counter++;
}

void casadi_f2_decref(void) {
  casadi_f2_ref_counter--;
  if (casadi_f2_ref_counter==0) {
    while (casadi_f2_mem_counter>0) {
      casadi_f2_free_mem(--casadi_f2_mem_counter);
    }
  }
}

/* constant_qp:(i0[45],i1[21])->(o0) */
static int casadi_f3(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  casadi_real a0;
  a0=0.;
  if (res[0]!=0) res[0][0]=a0;
  return 0;
}

/* arm_qp:(x0[45],p[21],lbx[45],ubx[45],lbg[355],ubg[355],lam_x0[45],lam_g0[355])->(x[45],f,g[355],lam_x[45],lam_g[355],lam_p[21]) */
static int casadi_f0(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  casadi_int i;
  casadi_real **res1=res+6, *rr, *w01=w+2335, *w02=w+2356, *w03=w+2611, *w04=w+2656, *w05=w+4796, *w06=w+5151, *w07=w+5506, *w14=w+5861, w15, *w16=w+5906;
  casadi_real *w17=w+6261, w18;
  const casadi_real **arg1=arg+8, *cr, *cs, *wr00, *wr01, *wr06, *wr07, *wr08, *wr09, *wr10, *wr11;
  int flag, mid;
  /* #0: @0 = input[0][0] */
  wr00 = arg[0] ? arg[0] : casadi_zeros;
  /* #1: @1 = input[1][0] */
  wr01 = arg[1] ? arg[1] : casadi_zeros;
  /* #2: {@2, @3, @4, @5, NULL, NULL} = arm_qp_qp(@0, @1) */
  arg1[0]=wr00;
  arg1[1]=wr01;
  res1[0]=w02;
  res1[1]=w03;
  res1[2]=w04;
  res1[3]=w05;
  res1[4]=0;
  res1[5]=0;
  if (casadi_f1(arg1, res1, iw, w, 0)) return 1;
  /* #3: @6 = input[4][0] */
  wr06 = arg[4] ? arg[4] : casadi_zeros;
  /* #4: @6 = (@6-@5) */
  for (i=0, rr=w06, cr=wr06, cs=w05; i<355; ++i) (*rr++)  = ((*cr++)-(*cs++));
  /* #5: @7 = input[5][0] */
  wr07 = arg[5] ? arg[5] : casadi_zeros;
  /* #6: @7 = (@7-@5) */
  for (i=0, rr=w07, cr=wr07, cs=w05; i<355; ++i) (*rr++)  = ((*cr++)-(*cs++));
  /* #7: @8 = input[2][0] */
  wr08 = arg[2] ? arg[2] : casadi_zeros;
  /* #8: @9 = input[3][0] */
  wr09 = arg[3] ? arg[3] : casadi_zeros;
  /* #9: @10 = input[6][0] */
  wr10 = arg[6] ? arg[6] : casadi_zeros;
  /* #10: @11 = input[7][0] */
  wr11 = arg[7] ? arg[7] : casadi_zeros;
  /* #11: @12 = 0x45 */
  /* #12: @13 = 0x0 */
  /* #13: {@14, @15, @16, @17} = arm_qp_qpsol(@2, @3, @4, @6, @7, @8, @9, @0, @10, @11, @12, @13) */
  arg1[0]=w02;
  arg1[1]=w03;
  arg1[2]=w04;
  arg1[3]=w06;
  arg1[4]=w07;
  arg1[5]=wr08;
  arg1[6]=wr09;
  arg1[7]=wr00;
  arg1[8]=wr10;
  arg1[9]=wr11;
  arg1[10]=0;
  arg1[11]=0;
  res1[0]=w14;
  res1[1]=(&w15);
  res1[2]=w16;
  res1[3]=w17;
  mid = casadi_f2_checkout();
  if (mid<0) return 1;
  flag = casadi_f2(arg1, res1, iw, w, mid);
  casadi_f2_release(mid);
  if (flag) return 1;
  /* #14: output[0][0] = @14 */
  casadi_copy(w14, 45, res[0]);
  /* #15: @18 = constant_qp(@0, @1) */
  arg1[0]=wr00;
  arg1[1]=wr01;
  res1[0]=(&w18);
  if (casadi_f3(arg1, res1, iw, w, 0)) return 1;
  /* #16: @18 = (@18+@15) */
  w18 += w15;
  /* #17: output[1][0] = @18 */
  if (res[1]) res[1][0] = w18;
  /* #18: @6 = zeros(355x1) */
  casadi_clear(w06, 355);
  /* #19: @6 = mac(@4,@14,@6) */
  casadi_mtimes(w04, casadi_s8, w14, casadi_s7, w06, casadi_s6, w, 0);
  /* #20: @6 = (@6+@5) */
  for (i=0, rr=w06, cs=w05; i<355; ++i) (*rr++) += (*cs++);
  /* #21: output[2][0] = @6 */
  casadi_copy(w06, 355, res[2]);
  /* #22: output[3][0] = @17 */
  casadi_copy(w17, 45, res[3]);
  /* #23: output[4][0] = @16 */
  casadi_copy(w16, 355, res[4]);
  /* #24: @1 = nan(21x1) */
  casadi_fill(w01, 21, casadi_nan);
  /* #25: output[5][0] = @1 */
  casadi_copy(w01, 21, res[5]);
  return 0;
}

